        ActionWithStates actionExt = new ActionWithStates();
        actionExt.status = "Ok";
        actionExt.action = action;
        actionExt.statesRequirements = new List<StateRequirements>();
        actionExt.errors = new List<string>();
        foreach (StateSummary state in EmptyStates)
        {
            List<ActionToStatesDefs> statesToAction = _context.ActionToStatesDefs.Where(a => a.ActionId == action.Id.ToString() && a.StateId == state.Id.ToString()).ToList();
            foreach (ActionToStatesDefs actReq in statesToAction)
            {
                StateRequirements myactionRequirements = GameHelpers.CreateStateRequirement(actionExt, actReq, state);
            }
        }
        var stage = _context.Stages.Where(a => a.ParentId == action.Id.ToString()).FirstOrDefault();
        if(stage!=null)
        {
            actionExt.hasStages = true;
        }
        else
        {
            actionExt.hasStages = false;
        }
        actionExt.canEdit = false;
        if (myuser!=null && myuser.IsAdmin==true)
        {
            actionExt.canEdit = true;
        }
        actionWithStates.Add(actionExt);
    }
    return await Task.Run(()=>actionWithStates);
